package com.tarapickle.identity.domain; import com.tarapickle.identity.domain.model.*; import org.junit.jupiter.api.Test; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*;
class OneTimeTokenTest {@Test void tokenExpiresAndIsSingleUse(){Instant now=Instant.parse("2026-08-21T10:00:00Z");VerificationToken t=new VerificationToken(UUID.randomUUID(),"hash",now,now.plusSeconds(60));assertThat(t.valid(now)).isTrue();t.use(now);assertThat(t.valid(now.plusSeconds(1))).isFalse();assertThatThrownBy(()->t.use(now.plusSeconds(1))).isInstanceOf(IllegalStateException.class);VerificationToken expired=new VerificationToken(UUID.randomUUID(),"other",now,now.plusSeconds(1));assertThat(expired.valid(now.plusSeconds(2))).isFalse();}}
